target.css:
:root {
  --ink: #203247;
  --muted: #647487;
  --paper: #fffdf8;
  --line: #d9e0df;
  --soft-blue: #edf5f7;
  --blue: #28768c;
  --deep-blue: #185367;
  --mint: #dff1e8;
  --green: #277657;
  --gold: #d8a64d;
  --white: #ffffff;
}

* {
  box-sizing: border-box;
}

.vault-monitor {
  width: 490px;
  margin: 38px auto;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.vault-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px 12px;
  border-bottom: 1px solid var(--line);
}

.title-block {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.eyebrow {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

h1,
h2,
p {
  margin: 0;
}

h1 {
  font-size: 18px;
  font-weight: 750;
  letter-spacing: -0.03em;
}

.status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 9px;
  color: var(--green);
  background: var(--mint);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 750;
}

.status-dot {
  width: 7px;
  height: 7px;
  background: var(--green);
  border-radius: 50%;
}

.vault-grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 10px;
  padding: 12px 16px;
}

.reading-card,
.control-card {
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 12px;
}

.reading-card {
  padding: 12px;
  background: var(--soft-blue);
}

.reading-top,
.control-heading,
.vault-footer,
.metric-list li {
  display: flex;
  align-items: center;
}

.reading-top {
  justify-content: space-between;
  gap: 8px;
}

h2 {
  font-size: 12px;
  font-weight: 750;
  letter-spacing: 0.01em;
}

.range-tag {
  padding: 3px 6px;
  color: var(--deep-blue);
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 5px;
  font-size: 9px;
  font-weight: 700;
}

.reading {
  display: flex;
  align-items: baseline;
  gap: 5px;
  margin-top: 7px;
  color: var(--deep-blue);
}

.reading strong {
  font-size: 31px;
  font-weight: 780;
  line-height: 1;
  letter-spacing: -0.06em;
}

.reading span {
  font-size: 12px;
  font-weight: 700;
}

.reading-note {
  margin-top: 3px;
  color: var(--green);
  font-size: 11px;
  font-weight: 650;
}

.meter {
  position: relative;
  height: 7px;
  margin-top: 11px;
  overflow: hidden;
  background: var(--white);
  border-radius: 99px;
}

.meter-fill {
  display: block;
  width: 62%;
  height: 100%;
  background: var(--blue);
  border-radius: inherit;
}

.meter-pin {
  position: absolute;
  top: -3px;
  left: 62%;
  width: 3px;
  height: 13px;
  background: var(--gold);
  border-radius: 2px;
}

.meter-labels {
  display: flex;
  justify-content: space-between;
  margin-top: 4px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 650;
}

.control-card {
  padding: 12px;
  background: var(--white);
}

.control-heading {
  justify-content: space-between;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--line);
}

.control-heading span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 650;
}

.metric-list {
  display: grid;
  gap: 1px;
  margin: 5px 0 0;
  padding: 0;
  list-style: none;
}

.metric-list li {
  gap: 7px;
  min-height: 25px;
  color: var(--muted);
  border-bottom: 1px solid var(--line);
  font-size: 11px;
  font-weight: 600;
}

.metric-list li:last-child {
  border-bottom: 0;
}

.metric-icon {
  display: grid;
  width: 17px;
  height: 17px;
  place-items: center;
  color: var(--blue);
  background: var(--soft-blue);
  border-radius: 5px;
  font-size: 13px;
  font-weight: 750;
}

.metric-list strong {
  margin-left: auto;
  color: var(--ink);
  font-size: 11px;
  font-weight: 750;
}

.vault-footer {
  justify-content: space-between;
  gap: 12px;
  padding: 10px 16px;
  background: var(--soft-blue);
  border-top: 1px solid var(--line);
}

.vault-footer p {
  color: var(--muted);
  font-size: 11px;
  font-weight: 650;
}

.shield {
  display: inline-grid;
  width: 15px;
  height: 15px;
  margin-right: 4px;
  place-items: center;
  color: var(--white);
  background: var(--green);
  border-radius: 50%;
  font-size: 10px;
}

button {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 10px;
  color: var(--white);
  background: var(--deep-blue);
  border: 0;
  border-radius: 7px;
  font-size: 11px;
  font-weight: 750;
}

button span {
  font-size: 14px;
  line-height: 0;
}

